/** Schema of public/data/birds.json (generated by scripts/build_data.py). */
export interface Attribution {
  author: string;
  license: string;
  licenseUrl?: string;
  sourceUrl: string;
}

export interface BirdImage extends Attribution {
  src: string;
}

export interface Recording {
  id: string;
  src: string;
  /** Xeno-canto sound type we fetched: 'song', 'call', 'bill clapping', ... */
  type: string;
  durationSec: number;
  sourceLengthSec?: number;
  quality?: string;
  recordist: string;
  license: string;
  licenseUrl?: string;
  sourceUrl: string;
  country?: string;
  location?: string;
  date?: string;
}

export interface Species {
  id: string;
  namePl: string;
  nameEn: string;
  nameLatin: string;
  family: string;
  habitat: string[];
  similarTo: string[];
  note: string;
  image: BirdImage | null;
  recordings: Recording[];
}

export interface BirdsData {
  version: number;
  generatedAt: string;
  species: Species[];
}
